#include <X11/Xlib.h>
#include <X11/Xutil.h>
#include <X11/extensions/Xrender.h>
#include <X11/extensions/Xfixes.h>
#include <X11/extensions/shape.h>
#include <pango/pangocairo.h>
#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>
