typedef struct {Display*d;int screen;Window root;XVisualInfo visual;Colormap map;} OinkX;
typedef struct {OinkX*x;Window id;} OinkWindow;
static pthread_once_t once=PTHREAD_ONCE_INIT;
static void init_threads(void){XInitThreads();}
void oink_x_close(OinkX*x){if(x){if(x->map)XFreeColormap(x->d,x->map);XCloseDisplay(x->d);free(x);}}
OinkX*oink_x_open(void){const char*s=getenv("XDG_SESSION_TYPE");if(s&&!strcmp(s,"wayland"))return NULL;pthread_once(&once,init_threads);Display*d=XOpenDisplay(NULL);if(!d)return NULL;OinkX*x=calloc(1,sizeof(*x));if(!x){XCloseDisplay(d);return NULL;}x->d=d;x->screen=DefaultScreen(d);x->root=RootWindow(d,x->screen);int event,error;if(!XFixesQueryExtension(d,&event,&error)||!XMatchVisualInfo(d,x->screen,32,TrueColor,&x->visual)){oink_x_close(x);return NULL;}XRenderPictFormat*f=XRenderFindVisualFormat(d,x->visual.visual);if(!f||!f->direct.alphaMask){oink_x_close(x);return NULL;}char name[64];snprintf(name,sizeof(name),"_NET_WM_CM_S%d",x->screen);if(XGetSelectionOwner(d,XInternAtom(d,name,False))==None){oink_x_close(x);return NULL;}x->map=XCreateColormap(d,x->root,x->visual.visual,AllocNone);return x;}
OinkWindow*oink_x_window(OinkX*x){OinkWindow*w=calloc(1,sizeof(*w));if(!w)return NULL;w->x=x;XSetWindowAttributes a;memset(&a,0,sizeof(a));a.colormap=x->map;a.border_pixel=0;a.background_pixel=0;a.override_redirect=True;a.event_mask=ButtonPressMask|ButtonReleaseMask|PointerMotionMask|LeaveWindowMask;w->id=XCreateWindow(x->d,x->root,0,0,1,1,0,32,InputOutput,x->visual.visual,CWColormap|CWBorderPixel|CWBackPixel|CWOverrideRedirect|CWEventMask,&a);XStoreName(x->d,w->id,"Oink overlay");XWMHints hint;memset(&hint,0,sizeof(hint));hint.flags=InputHint;hint.input=False;XSetWMHints(x->d,w->id,&hint);XserverRegion region=XFixesCreateRegion(x->d,NULL,0);XFixesSetWindowShapeRegion(x->d,w->id,ShapeInput,0,0,region);XFixesDestroyRegion(x->d,region);return w;}
uint64_t oink_x_window_id(OinkWindow*w){return w->id;}
void oink_x_window_close(OinkWindow*w){if(w){XDestroyWindow(w->x->d,w->id);XFlush(w->x->d);free(w);}}
void oink_x_hide(OinkWindow*w){XUnmapWindow(w->x->d,w->id);XFlush(w->x->d);}
int oink_x_present(OinkWindow*w,int x,int y,unsigned width,unsigned height,const uint32_t*pixels,int interactive){if(!width||!height||width>8192||height>8192)return -1;OinkX*c=w->x;XMoveResizeWindow(c->d,w->id,x,y,width,height);XMapRaised(c->d,w->id);XImage*image=XCreateImage(c->d,c->visual.visual,32,ZPixmap,0,(char*)pixels,width,height,32,0);if(!image)return -1;GC gc=XCreateGC(c->d,w->id,0,NULL);XPutImage(c->d,w->id,gc,image,0,0,0,0,width,height);image->data=NULL;XDestroyImage(image);XFreeGC(c->d,gc);
 XRectangle*rects=NULL;int count=0;if(interactive){rects=malloc((size_t)width*height*sizeof(XRectangle));if(!rects)return -1;for(unsigned row=0;row<height;row++){unsigned col=0;while(col<width){while(col<width&&!(pixels[(size_t)row*width+col]>>24))col++;unsigned start=col;while(col<width&&(pixels[(size_t)row*width+col]>>24))col++;if(col>start){XRectangle r={(short)start,(short)row,(unsigned short)(col-start),1};rects[count++]=r;}}}}
 XserverRegion input=XFixesCreateRegion(c->d,rects,count);XFixesSetWindowShapeRegion(c->d,w->id,ShapeInput,0,0,input);XFixesDestroyRegion(c->d,input);free(rects);XMapRaised(c->d,w->id);XFlush(c->d);return 0;}
/* Drain only this dedicated display connection; never inspect other applications. */
int oink_x_event(OinkX*x,uint64_t*window,int*kind,int*px,int*py){while(XPending(x->d)){XEvent e;XNextEvent(x->d,&e);if(e.type==MotionNotify){*window=e.xmotion.window;*kind=3;*px=e.xmotion.x;*py=e.xmotion.y;return 1;}if(e.type==LeaveNotify){*window=e.xcrossing.window;*kind=4;*px=e.xcrossing.x;*py=e.xcrossing.y;return 1;}if((e.type==ButtonPress||e.type==ButtonRelease)&&e.xbutton.button==Button1){*window=e.xbutton.window;*kind=e.type==ButtonPress?1:2;*px=e.xbutton.x;*py=e.xbutton.y;return 1;}}return 0;}
typedef struct {uint8_t*alpha;size_t width,height;double cap_top,advance,left;} OinkMask;
int oink_text_mask(const char*text,double cap,int weight,OinkMask*out){if(!text||!out||cap<=0||cap>512)return -1;memset(out,0,sizeof(*out));PangoFontMap*map=pango_cairo_font_map_new();PangoContext*context=pango_font_map_create_context(map);PangoLayout*layout=pango_layout_new(context);PangoFontDescription*font=pango_font_description_new();pango_font_description_set_family(font,"Sans");pango_font_description_set_weight(font,(PangoWeight)weight);pango_font_description_set_absolute_size(font,cap/0.72*PANGO_SCALE);pango_layout_set_font_description(layout,font);pango_layout_set_text(layout,"H",-1);PangoRectangle h,logical;pango_layout_get_pixel_extents(layout,&h,&logical);if(h.height>0){pango_font_description_set_absolute_size(font,cap/0.72*PANGO_SCALE*cap/h.height);pango_layout_set_font_description(layout,font);pango_layout_get_pixel_extents(layout,&h,&logical);}pango_layout_set_text(layout,text,-1);pango_layout_set_single_paragraph_mode(layout,TRUE);PangoRectangle ink;pango_layout_get_pixel_extents(layout,&ink,&logical);int width=ink.width+4,height=ink.height+4;if(width<1)width=1;if(height<1)height=1;if(width>16384||height>2048){pango_font_description_free(font);g_object_unref(layout);g_object_unref(context);g_object_unref(map);return -1;}cairo_surface_t*surface=cairo_image_surface_create(CAIRO_FORMAT_A8,width,height);cairo_t*cr=cairo_create(surface);cairo_set_source_rgba(cr,1,1,1,1);cairo_move_to(cr,2-ink.x,2-ink.y);pango_cairo_show_layout(cr,layout);cairo_surface_flush(surface);out->alpha=malloc((size_t)width*height);if(out->alpha){unsigned char*data=cairo_image_surface_get_data(surface);int stride=cairo_image_surface_get_stride(surface);for(int row=0;row<height;row++)memcpy(out->alpha+(size_t)row*width,data+(size_t)row*stride,width);out->width=width;out->height=height;out->advance=logical.width;out->left=2-ink.x;out->cap_top=2-ink.y+h.y;}cairo_destroy(cr);cairo_surface_destroy(surface);pango_font_description_free(font);g_object_unref(layout);g_object_unref(context);g_object_unref(map);return out->alpha?0:-1;}
void oink_text_mask_free(OinkMask*mask){free(mask->alpha);mask->alpha=NULL;}

int oink_x_probe(OinkWindow*w,uint32_t*pixel,int*rectangles,int*focusable){XSync(w->x->d,False);XImage*image=XGetImage(w->x->d,w->id,0,0,1,1,AllPlanes,ZPixmap);if(!image)return -1;*pixel=(uint32_t)XGetPixel(image,0,0);XDestroyImage(image);int order=0,count=0;XRectangle*r=XShapeGetRectangles(w->x->d,w->id,ShapeInput,&count,&order);if(r)XFree(r);*rectangles=count;XWMHints*h=XGetWMHints(w->x->d,w->id);*focusable=!h||!(h->flags&InputHint)||h->input;if(h)XFree(h);return 0;}
